/* data/calendar.json — the seed of Administrare › Calendar (calendar-v1, 2026-10-26).
   The national holidays are computed by the same engine the app uses (js/working-days.js); the manual days are
   demo examples (a government day transfer, one authority's own day, a generated holiday edited by hand).
   Run: node tools/calendar/seed.mjs */
import fs from "node:fs";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const WD = require("../../js/working-days.js");

const ADMIN = "Anastasia Cojocaru";
const days = [];
/* 2025 + 2026 generated by the yearly job of 1 January 2025, 2027 by the job of 1 January 2026 (US-288 AC-03) */
const generatedAt = { 2025: "2025-01-01T00:00:00", 2026: "2025-01-01T00:00:00", 2027: "2026-01-01T00:00:00" };
for (const year of [2025, 2026, 2027]) {
  WD.nationalHolidays(year).filter((h) => !h.weekend).forEach((h) => days.push({
    id: `cal-${h.date}`, date: h.date, type: "nelucratoare", reason: h.reason, authority: null,
    source: "Generat", deleted: false, createdBy: "SIA GEAP", createdAt: generatedAt[year]
  }));
}
/* 31 August 2026: the generated holiday, its reason corrected by hand → source „Manual” (US-285 AC-04) */
const aug31 = days.find((d) => d.date === "2026-08-31");
Object.assign(aug31, { reason: "Ziua Limbii Române („Limba noastră”), sărbătoare națională", source: "Manual", editedBy: ADMIN, editedAt: "2026-08-03T11:20:00" });
days.push(
  /* a government transfer (example): Friday 2 January off, worked on Saturday 10 January */
  { id: "cal-2026-01-02", date: "2026-01-02", type: "nelucratoare", reason: "Transfer: zi de odihnă, lucrată sâmbătă, 10 ianuarie", authority: null, source: "Manual", deleted: false, createdBy: ADMIN, createdAt: "2025-12-15T10:12:00" },
  { id: "cal-2026-01-10", date: "2026-01-10", type: "lucratoare", reason: "Transfer: zi lucrătoare pentru vineri, 2 ianuarie", authority: null, source: "Manual", deleted: false, createdBy: ADMIN, createdAt: "2025-12-15T10:14:00" },
  /* one authority's own day (example): the country keeps working */
  { id: "cal-2026-04-07-ansp", date: "2026-04-07", type: "nelucratoare", reason: "Ziua Mondială a Sănătății, zi liberă pentru personalul ANSP", authority: "ANSP", source: "Manual", deleted: false, createdBy: ADMIN, createdAt: "2026-03-20T09:40:00" }
);
days.sort((a, b) => a.date.localeCompare(b.date) || String(a.authority || "").localeCompare(String(b.authority || "")));

const journal = [
  { at: "2026-08-03T11:20:00", user: ADMIN, role: "Administrator central", type: "Zi editată", status: "Reușit", detail: "31 august 2026 · Zi nelucrătoare · Toată țara · sursa a devenit „Manual”. Termenele a 88 de dosare active au fost recalculate: niciunul nu s-a schimbat." },
  { at: "2026-03-20T09:40:00", user: ADMIN, role: "Administrator central", type: "Zi adăugată", status: "Reușit", detail: "7 aprilie 2026 · Zi nelucrătoare · ANSP. Termenele a 88 de dosare active au fost recalculate: 3 s-au schimbat." },
  { at: "2026-01-01T00:15:00", user: "SIA GEAP", role: "Sistem", type: "Recalculare termene", status: "Reușit", detail: "Recalcularea de rezervă de la schimbarea anului: 88 de dosare active, 0 termene modificate." },
  { at: "2026-01-01T00:00:00", user: "SIA GEAP", role: "Sistem", type: "Resetare contoare", status: "Reușit", detail: "Contoarele numerelor de acte cu resetare anuală au repornit de la 1 pentru 2026." },
  { at: "2026-01-01T00:00:00", user: "SIA GEAP", role: "Sistem", type: "Generare anuală", status: "Reușit", detail: "2026: sărbătorile legale erau deja în calendar. 2027: au fost adăugate 9 sărbători legale." },
  { at: "2025-12-15T10:14:00", user: ADMIN, role: "Administrator central", type: "Zi adăugată", status: "Reușit", detail: "10 ianuarie 2026 · Zi lucrătoare · Toată țara." },
  { at: "2025-12-15T10:12:00", user: ADMIN, role: "Administrator central", type: "Zi adăugată", status: "Reușit", detail: "2 ianuarie 2026 · Zi nelucrătoare · Toată țara." }
];

const out = {
  note: "Administrare › Calendar (Feature 93686, US-283…288). Exceptions to Monday–Friday; national holidays generated by js/working-days.js (tools/calendar/seed.mjs). Manual days are demo examples.",
  eventTypes: [["nelucratoare", "Zi nelucrătoare"], ["lucratoare", "Zi lucrătoare"]],
  days,
  journal,
  seq: 100
};
fs.writeFileSync(new URL("../../data/calendar.json", import.meta.url), `${JSON.stringify(out, null, 2)}\n`);
console.log(`days ${days.length}, journal ${journal.length}`);
